def accuracy(preds, labels):
    if not labels:
        return 0.0
    correct = sum(1 for pred, label in zip(preds, labels) if pred == label)
    return round(correct / len(labels), 2)

def minmax(values):
    if not values:
        return []
    low = min(values)
    high = max(values)
    if low == high:
        return [0.0 for _ in values]
    return [round((value - low) / (high - low), 4) for value in values]

def count_extended_fingers(landmarks):
    pairs = [(8, 6), (12, 10), (16, 14), (20, 18)]
    count = 0
    for tip, pip in pairs:
        if landmarks[tip][1] < landmarks[pip][1]:
            count += 1
    return count

def classify_rps(fingers):
    if fingers == 0:
        return 'rock'
    if fingers == 4:
        return 'paper'
    if fingers == 2:
        return 'scissors'
    return 'unknown'

